// Generates src/bundled.generated.ts from bundled/profiles/*.yaml and bundled/packs/*.yaml.
//
// Why: the CLI ships as one bundled JS file and cannot read YAML from disk at runtime, so the
// starter profiles and the `core` pack are embedded as string constants. The generated file is
// committed; scripts/gen-bundled.test.mjs fails when it is stale.
//
// Usage: pnpm --filter @prosegate/profiles gen:bundled

import { readdirSync, readFileSync, realpathSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
export const PROFILES_DIR = join(here, "..", "bundled", "profiles");
export const PACKS_DIR = join(here, "..", "bundled", "packs");
export const OUTPUT_FILE = join(here, "..", "src", "bundled.generated.ts");

/** `pr-description.yaml` -> `PR_DESCRIPTION_YAML` (profiles); `core.yaml` -> `CORE_PACK_YAML` (packs). */
export function constantName(file, kind) {
  const base = file.replace(/\.yaml$/, "").replace(/-/g, "_").toUpperCase();
  return kind === "pack" ? `${base}_PACK_YAML` : `${base}_YAML`;
}

/** The full text of the generated module. Line endings are normalised to LF. */
export function render() {
  const lines = [
    "// GENERATED by scripts/gen-bundled.mjs from bundled/profiles/*.yaml and bundled/packs/*.yaml. Do not edit by hand.",
    "// Regenerate with: pnpm --filter @prosegate/profiles gen:bundled",
    "",
  ];
  for (const [dir, kind] of [
    [PROFILES_DIR, "profile"],
    [PACKS_DIR, "pack"],
  ]) {
    const files = readdirSync(dir)
      .filter((f) => f.endsWith(".yaml"))
      .sort();
    for (const file of files) {
      const text = readFileSync(join(dir, file), "utf8").replace(/\r\n/g, "\n");
      lines.push(`export const ${constantName(file, kind)} = ${JSON.stringify(text)};`, "");
    }
  }
  return lines.join("\n");
}

function main() {
  writeFileSync(OUTPUT_FILE, render());
  process.stdout.write(`wrote ${OUTPUT_FILE}\n`);
}

const entry = process.argv[1];
if (entry && realpathSync(fileURLToPath(import.meta.url)) === realpathSync(entry)) main();
